def put_item(table_id, pk, attributes, sk=None, **_extra):
    import json, os, datetime, time, hashlib, uuid, math, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0556000" if __import__("os").path.isdir("./environment_mix/0556000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        n = uuid.uuid4().int
        s = []
        for _ in range(17):
            s.append(alphabet[n % 36]); n //= 36
        return prefix + "_" + "".join(s)

    def _canon_sha256(obj):
        try:
            s = json.dumps(obj, sort_keys=True, separators=(",", ":"), ensure_ascii=False)
        except TypeError:
            return None
        return hashlib.sha256(s.encode("utf-8")).hexdigest()

    def _parse_typed(v, field):
        if not isinstance(v, dict):
            return None, _err("VALIDATION_ERROR", f"{field} must be an object with a single typed value (S, N, or B)", field=field)
        extra_keys = [k for k in v.keys() if k not in ("S", "N", "B")]
        if extra_keys:
            return None, _err("VALIDATION_ERROR", f"{field} contains invalid key '{extra_keys[0]}'", field=field)
        present = [k for k in ("S", "N", "B") if k in v and v.get(k) is not None]
        if len(present) != 1:
            return None, _err("VALIDATION_ERROR", f"{field} must contain exactly one of S, N, or B", field=field)
        k = present[0]
        val = v.get(k)
        if k in ("S", "B"):
            if not isinstance(val, str):
                return None, _err("VALIDATION_ERROR", f"{field}.{k} must be a string", field=field)
            return (k, val), None
        if (not isinstance(val, (int, float))) or isinstance(val, bool):
            return None, _err("VALIDATION_ERROR", f"{field}.N must be a number", field=field)
        if isinstance(val, float) and (math.isnan(val) or math.isinf(val)):
            return None, _err("VALIDATION_ERROR", f"{field}.N must be a finite number", field=field)
        return (k, float(val)), None

    def _match_table_id(tid, tables_rows):
        # Relax overly-strict pattern: accept any string that matches an existing table_id in the datastore.
        if not isinstance(tid, str) or not tid:
            return False
        if re.match(r"^ddb_tbl_[0-9A-Z]{17}$", tid):
            return True
        return any(isinstance(t, dict) and t.get("table_id") == tid for t in tables_rows)

    def _append_log(op_logs, account_id_val, table_id_val, response_obj, ok, err_code=None, err_msg=None, rcu=0.0, wcu=0.0, http_status=None):
        op_logs.append({
            "op_id": _new_id("ddb_op"),
            "account_id": account_id_val if isinstance(account_id_val, str) and account_id_val else "unknown",
            "table_id": table_id_val,
            "index_id": None,
            "tool_name": "put_item",
            "request": {"table_id": table_id, "pk": pk, "sk": sk, "attributes": attributes},
            "response": response_obj,
            "http_status": http_status,
            "consumed_read_units": float(rcu),
            "consumed_write_units": float(wcu),
            "duration_ms": max(0, int((time.time() - _t0) * 1000)),
            "status": "SUCCEEDED" if ok else "FAILED",
            "error_code": err_code,
            "error_message": err_msg,
            "created_at": now,
            "updated_at": now,
        })

    op_logs = _load("ddb_operation_logs.json")
    tables = _load("ddb_tables.json")
    items = _load("ddb_items.json")

    # Validate
    if not _match_table_id(table_id, tables):
        er = _err("VALIDATION_ERROR", "table_id does not match expected format", field="table_id")
        _append_log(op_logs, "unknown", table_id, er, False, err_code="ValidationException", err_msg=er["error"]["message"])
        _save("ddb_operation_logs.json", op_logs)
        return er

    table = next((t for t in tables if isinstance(t, dict) and t.get("table_id") == table_id), None)
    if not table:
        er = _err("NOT_FOUND", "table_id not found", field="table_id")
        _append_log(op_logs, "unknown", table_id, er, False, err_code="ResourceNotFoundException", err_msg=er["error"]["message"], rcu=1.0)
        _save("ddb_operation_logs.json", op_logs)
        return er

    if table.get("status") in ("DELETING", "FAILED"):
        er = _err("CONFLICT", f"table is not writable in status {table.get('status')}", field="status")
        _append_log(op_logs, table.get("account_id"), table_id, er, False, err_code="ResourceInUseException", err_msg=er["error"]["message"], rcu=1.0)
        _save("ddb_operation_logs.json", op_logs)
        return er

    if not isinstance(attributes, dict):
        er = _err("VALIDATION_ERROR", "attributes must be an object", field="attributes")
        _append_log(op_logs, table.get("account_id"), table_id, er, False, err_code="ValidationException", err_msg=er["error"]["message"], rcu=0.0)
        _save("ddb_operation_logs.json", op_logs)
        return er

    pk_parsed, e = _parse_typed(pk, "pk")
    if e:
        _append_log(op_logs, table.get("account_id"), table_id, e, False, err_code="ValidationException", err_msg=e["error"]["message"])
        _save("ddb_operation_logs.json", op_logs)
        return e

    has_sort_key = table.get("range_key_name") is not None
    if has_sort_key and sk is None:
        er = _err("VALIDATION_ERROR", "sk is required for tables with a sort key", field="sk")
        _append_log(op_logs, table.get("account_id"), table_id, er, False, err_code="ValidationException", err_msg=er["error"]["message"])
        _save("ddb_operation_logs.json", op_logs)
        return er
    if (not has_sort_key) and sk is not None:
        er = _err("VALIDATION_ERROR", "sk must not be provided for tables without a sort key", field="sk")
        _append_log(op_logs, table.get("account_id"), table_id, er, False, err_code="ValidationException", err_msg=er["error"]["message"])
        _save("ddb_operation_logs.json", op_logs)
        return er

    sk_parsed = None
    if sk is not None:
        sk_parsed, e = _parse_typed(sk, "sk")
        if e:
            _append_log(op_logs, table.get("account_id"), table_id, e, False, err_code="ValidationException", err_msg=e["error"]["message"])
            _save("ddb_operation_logs.json", op_logs)
            return e

    # Type match against table schema
    expected_pk_type = table.get("hash_key_type")
    if pk_parsed[0] != expected_pk_type:
        er = _err("VALIDATION_ERROR", f"pk type {pk_parsed[0]} does not match table hash_key_type {expected_pk_type}", field="pk")
        _append_log(op_logs, table.get("account_id"), table_id, er, False, err_code="ValidationException", err_msg=er["error"]["message"])
        _save("ddb_operation_logs.json", op_logs)
        return er

    if has_sort_key:
        expected_sk_type = table.get("range_key_type")
        if sk_parsed[0] != expected_sk_type:
            er = _err("VALIDATION_ERROR", f"sk type {sk_parsed[0]} does not match table range_key_type {expected_sk_type}", field="sk")
            _append_log(op_logs, table.get("account_id"), table_id, er, False, err_code="ValidationException", err_msg=er["error"]["message"])
            _save("ddb_operation_logs.json", op_logs)
            return er

    # Throughput / billing rules (simplified but enforced)
    # Each write costs 1 WCU. Reject if PROVISIONED and WCU is 0/None or obviously exceeded.
    billing_mode = table.get("billing_mode")
    if billing_mode == "PROVISIONED":
        wcu_limit = table.get("write_capacity_units")
        if not isinstance(wcu_limit, int) or wcu_limit < 1:
            er = _err("CONFLICT", "table has invalid provisioned write capacity configuration", field="write_capacity_units")
            _append_log(op_logs, table.get("account_id"), table_id, er, False, err_code="ResourceInUseException", err_msg=er["error"]["message"], rcu=0.0, wcu=0.0)
            _save("ddb_operation_logs.json", op_logs)
            return er
        # crude throttle: if last second already used >= wcu_limit, reject
        window_start = (now_dt - datetime.timedelta(seconds=1)).isoformat() + "Z"
        recent_writes = 0.0
        for r in op_logs:
            if isinstance(r, dict) and r.get("table_id") == table_id and r.get("created_at") >= window_start:
                recent_writes += float(r.get("consumed_write_units") or 0.0)
        if recent_writes + 1.0 > float(wcu_limit) * 1.05:
            er = _err("RATE_LIMIT", "provisioned throughput exceeded", limit=wcu_limit)
            _append_log(op_logs, table.get("account_id"), table_id, er, False, err_code="ProvisionedThroughputExceededException", err_msg="ProvisionedThroughputExceededException: write capacity exceeded", wcu=0.0)
            _save("ddb_operation_logs.json", op_logs)
            return er

    # Upsert by composite key
    pk_type, pk_val = pk_parsed
    sk_type, sk_val = (sk_parsed if sk_parsed else (None, None))

    def _key_fields_for_type(prefix, t):
        return {"S": f"{prefix}_s", "N": f"{prefix}_n", "B": f"{prefix}_b"}[t]

    pk_field = _key_fields_for_type("pk", pk_type)
    sk_field = _key_fields_for_type("sk", sk_type) if sk_type else None

    def _same_key(it):
        if it.get("table_id") != table_id:
            return False
        if it.get(pk_field) != pk_val:
            return False
        # ensure other pk fields null-ish
        for f in ("pk_s", "pk_n", "pk_b"):
            if f != pk_field and it.get(f) is not None:
                return False
        if has_sort_key:
            if it.get(sk_field) != sk_val:
                return False
            for f in ("sk_s", "sk_n", "sk_b"):
                if f != sk_field and it.get(f) is not None:
                    return False
        else:
            if any(it.get(f) is not None for f in ("sk_s", "sk_n", "sk_b")):
                return False
        return True

    existing_idx = None
    for idx, it in enumerate(items):
        if isinstance(it, dict) and _same_key(it):
            existing_idx = idx
            break

    sha = _canon_sha256(attributes)
    if sha is None or not re.match(r"^[a-f0-9]{64}$", sha):
        er = _err("VALIDATION_ERROR", "attributes must be JSON-serializable; could not compute attributes_sha256", field="attributes")
        _append_log(op_logs, table.get("account_id"), table_id, er, False, err_code="ValidationException", err_msg=er["error"]["message"])
        _save("ddb_operation_logs.json", op_logs)
        return er

    if existing_idx is None:
        row = {
            "item_id": _new_id("ddb_itm"),
            "table_id": table_id,
            "pk_s": None, "pk_n": None, "pk_b": None,
            "sk_s": None, "sk_n": None, "sk_b": None,
            "attributes": attributes,
            "attributes_sha256": sha,
            "status": "ACTIVE",
            "version": 1,
            "created_at": now,
            "updated_at": now,
        }
        row[pk_field] = pk_val
        if has_sort_key:
            row[sk_field] = sk_val
        items.append(row)
        _save("ddb_items.json", items)
        resp = {"item": row}
        _append_log(op_logs, table.get("account_id"), table_id, resp, True, rcu=0.0, wcu=1.0)
        _save("ddb_operation_logs.json", op_logs)
        return resp

    # replace existing item entirely
    old = items[existing_idx]
    new_row = {
        "item_id": old.get("item_id") or _new_id("ddb_itm"),
        "table_id": table_id,
        "pk_s": None, "pk_n": None, "pk_b": None,
        "sk_s": None, "sk_n": None, "sk_b": None,
        "attributes": attributes,
        "attributes_sha256": sha,
        "status": "ACTIVE",
        "version": int(old.get("version") or 0) + 1 if int(old.get("version") or 0) >= 1 else 1,
        "created_at": old.get("created_at") or now,
        "updated_at": now,
    }
    new_row[pk_field] = pk_val
    if has_sort_key:
        new_row[sk_field] = sk_val
    items[existing_idx] = new_row
    _save("ddb_items.json", items)
    resp = {"item": new_row}
    _append_log(op_logs, table.get("account_id"), table_id, resp, True, rcu=0.0, wcu=1.0)
    _save("ddb_operation_logs.json", op_logs)
    return resp

