                _save("ddb_operation_logs.json", op_logs)
                return er

    resp = {"item": found} if found else {"item": None}
    _append_log(op_logs, table.get("account_id"), table_id, resp, True, rcu=1.0, wcu=0.0)
    _save("ddb_operation_logs.json", op_logs)
    return resp

def query_table(table_id, pk, index_id=None, sk_condition=None, filter=None, limit=None, cursor=None, scan_index_forward=None, consistent_read=None, **_extra):
