    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        n = uuid.uuid4().int
        s = []
        for _ in range(17):
            s.append(alphabet[n % 36]); n //= 36
        return prefix + "_" + "".join(s)

    def _parse_typed(v, field):
        if not isinstance(v, dict):
            return None, _err("VALIDATION_ERROR", f"{field} must be an object with a single typed value (S, N, or B)", field=field)
        extra_keys = [k for k in v.keys() if k not in ("S", "N", "B")]
        if extra_keys:
            return None, _err("VALIDATION_ERROR", f"{field} contains invalid key '{extra_keys[0]}'", field=field)
        present = [k for k in ("S", "N", "B") if k in v and v.get(k) is not None]
        if len(present) != 1:
            return None, _err("VALIDATION_ERROR", f"{field} must contain exactly one of S, N, or B", field=field)
        k = present[0]
        val = v.get(k)
        if k in ("S", "B"):
            if not isinstance(val, str):
                return None, _err("VALIDATION_ERROR", f"{field}.{k} must be a string", field=field)
            return (k, val), None
        if (not isinstance(val, (int, float))) or isinstance(val, bool):
            return None, _err("VALIDATION_ERROR", f"{field}.N must be a number", field=field)
        if isinstance(val, float) and (math.isnan(val) or math.isinf(val)):
            return None, _err("VALIDATION_ERROR", f"{field}.N must be a finite number", field=field)
        return (k, float(val)), None

    def _match_table_id(tid, tables_rows):
        if not isinstance(tid, str) or not tid:
            return False
        if re.match(r"^ddb_tbl_[0-9A-Z]{17}$", tid):
            return True
        return any(isinstance(t, dict) and t.get("table_id") == tid for t in tables_rows)

    def _decode_cursor(cur):
        if cur is None:
            return None
        if isinstance(cur, str):
            # Accept opaque cursors; support base64 json, otherwise treat as simple offset marker.
            try:
                raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"===").decode("utf-8")
                obj = json.loads(raw)
                if isinstance(obj, dict):
                    return obj
            except Exception:
                return {"after": cur}
        return None

    def _make_cursor(obj):
        raw = json.dumps(obj, separators=(",", ":"), sort_keys=True)
        return base64.urlsafe_b64encode(raw.encode("utf-8")).decode("utf-8").rstrip("=")

    def _append_log(op_logs, account_id_val, table_id_val, index_id_val, response_obj, ok, err_code=None, err_msg=None, rcu=0.0, wcu=0.0, http_status=None):
        op_logs.append({
            "op_id": _new_id("ddb_op"),
            "account_id": account_id_val if isinstance(account_id_val, str) and account_id_val else "unknown",
            "table_id": table_id_val,
            "index_id": index_id_val,
            "tool_name": "query_table",
            "request": {"table_id": table_id, "index_id": index_id, "pk": pk, "sk_condition": sk_condition, "filter": filter, "limit": limit, "cursor": cursor, "scan_index_forward": scan_index_forward, "consistent_read": consistent_read},
            "response": response_obj,
            "http_status": http_status,
            "consumed_read_units": float(rcu),
            "consumed_write_units": float(wcu),
            "duration_ms": max(0, int((time.time() - _t0) * 1000)),
            "status": "SUCCEEDED" if ok else "FAILED",
            "error_code": err_code,
            "error_message": err_msg,
            "created_at": now,
            "updated_at": now,
        })

    op_logs = _load("ddb_operation_logs.json")
    tables = _load("ddb_tables.json")
    indexes = _load("ddb_indexes.json")
    items = _load("ddb_items.json")

    if not _match_table_id(table_id, tables):
        er = _err("VALIDATION_ERROR", "table_id does not match expected format", field="table_id")
        _append_log(op_logs, "unknown", table_id, index_id, er, False, err_code="ValidationException", err_msg=er["error"]["message"])
        _save("ddb_operation_logs.json", op_logs)
        return er

    table = next((t for t in tables if isinstance(t, dict) and t.get("table_id") == table_id), None)
    if not table:
        er = _err("NOT_FOUND", "table_id not found", field="table_id")
        _append_log(op_logs, "unknown", table_id, index_id, er, False, err_code="ResourceNotFoundException", err_msg=er["error"]["message"], rcu=1.0)
        _save("ddb_operation_logs.json", op_logs)
        return er

    if table.get("status") in ("DELETING", "FAILED"):
        er = _err("CONFLICT", f"table is not readable in status {table.get('status')}", field="status")
        _append_log(op_logs, table.get("account_id"), table_id, index_id, er, False, err_code="ResourceInUseException", err_msg=er["error"]["message"], rcu=1.0)
        _save("ddb_operation_logs.json", op_logs)
        return er

    # Resolve key schema (base table or index)
    key_hash_type = table.get("hash_key_type")
    key_range_type = table.get("range_key_type")
    if index_id is not None:
        if not isinstance(index_id, str) or not re.match(r"^ddb_idx_[0-9A-Z]{17}$", index_id):
            er = _err("VALIDATION_ERROR", "index_id does not match expected format", field="index_id")
            _append_log(op_logs, table.get("account_id"), table_id, index_id, er, False, err_code="ValidationException", err_msg=er["error"]["message"])
            _save("ddb_operation_logs.json", op_logs)
            return er
        idx_row = next((ix for ix in indexes if isinstance(ix, dict) and ix.get("index_id") == index_id and ix.get("table_id") == table_id), None)
        if not idx_row:
            er = _err("NOT_FOUND", "index_id not found for table", field="index_id")
            _append_log(op_logs, table.get("account_id"), table_id, index_id, er, False, err_code="ResourceNotFoundException", err_msg=er["error"]["message"], rcu=1.0)
            _save("ddb_operation_logs.json", op_logs)
            return er
        # key types come from index definition
        key_hash_type = idx_row.get("hash_key_type")
        key_range_type = idx_row.get("range_key_type")

    pk_parsed, e = _parse_typed(pk, "pk")
    if e:
        _append_log(op_logs, table.get("account_id"), table_id, index_id, e, False, err_code="ValidationException", err_msg=e["error"]["message"])
        _save("ddb_operation_logs.json", op_logs)
        return e
    if pk_parsed[0] != key_hash_type:
        er = _err("VALIDATION_ERROR", f"pk type {pk_parsed[0]} does not match key schema hash type {key_hash_type}", field="pk")
        _append_log(op_logs, table.get("account_id"), table_id, index_id, er, False, err_code="ValidationException", err_msg=er["error"]["message"])
        _save("ddb_operation_logs.json", op_logs)
        return er

    # Parse and validate sk_condition
    cond = None
    if sk_condition is not None:
        if not isinstance(sk_condition, dict) or "operator" not in sk_condition:
            er = _err("VALIDATION_ERROR", "sk_condition must be an object with operator", field="sk_condition")
            _append_log(op_logs, table.get("account_id"), table_id, index_id, er, False, err_code="ValidationException", err_msg=er["error"]["message"])
            _save("ddb_operation_logs.json", op_logs)
            return er
        op = sk_condition.get("operator")
        if op not in ("EQ", "LT", "LE", "GT", "GE", "BETWEEN", "BEGINS_WITH"):
            er = _err("VALIDATION_ERROR", "invalid sk_condition.operator", field="sk_condition.operator")
            _append_log(op_logs, table.get("account_id"), table_id, index_id, er, False, err_code="ValidationException", err_msg=er["error"]["message"])
            _save("ddb_operation_logs.json", op_logs)
            return er
        if key_range_type is None:
            er = _err("VALIDATION_ERROR", "sk_condition is not allowed on a key schema without a sort key", field="sk_condition")
            _append_log(op_logs, table.get("account_id"), table_id, index_id, er, False, err_code="ValidationException", err_msg=er["error"]["message"])
            _save("ddb_operation_logs.json", op_logs)
            return er
        if op == "BETWEEN":
            between = sk_condition.get("between")
            if not (isinstance(between, list) and len(between) == 2):
                er = _err("VALIDATION_ERROR", "BETWEEN requires between to be an array of exactly two typed values", field="sk_condition.between")
                _append_log(op_logs, table.get("account_id"), table_id, index_id, er, False, err_code="ValidationException", err_msg=er["error"]["message"])
                _save("ddb_operation_logs.json", op_logs)
                return er
            v1, e1 = _parse_typed(between[0], "sk_condition.between[0]")
            v2, e2 = _parse_typed(between[1], "sk_condition.between[1]")
            if e1 or e2:
                er = e1 or e2
                _append_log(op_logs, table.get("account_id"), table_id, index_id, er, False, err_code="ValidationException", err_msg=er["error"]["message"])
                _save("ddb_operation_logs.json", op_logs)
                return er
            if v1[0] != key_range_type or v2[0] != key_range_type:
                er = _err("VALIDATION_ERROR", "BETWEEN values must match sort key type", field="sk_condition.between")
                _append_log(op_logs, table.get("account_id"), table_id, index_id, er, False, err_code="ValidationException", err_msg=er["error"]["message"])
                _save("ddb_operation_logs.json", op_logs)
                return er
            cond = {"op": "BETWEEN", "low": v1[1], "high": v2[1], "type": v1[0]}
        else:
            if "value" not in sk_condition:
                er = _err("VALIDATION_ERROR", f"{op} requires value", field="sk_condition.value")
                _append_log(op_logs, table.get("account_id"), table_id, index_id, er, False, err_code="ValidationException", err_msg=er["error"]["message"])
                _save("ddb_operation_logs.json", op_logs)
                return er
            v, ev = _parse_typed(sk_condition.get("value"), "sk_condition.value")
            if ev:
                _append_log(op_logs, table.get("account_id"), table_id, index_id, ev, False, err_code="ValidationException", err_msg=ev["error"]["message"])
                _save("ddb_operation_logs.json", op_logs)
                return ev
            if v[0] != key_range_type:
                er = _err("VALIDATION_ERROR", "sk_condition.value must match sort key type", field="sk_condition.value")
                _append_log(op_logs, table.get("account_id"), table_id, index_id, er, False, err_code="ValidationException", err_msg=er["error"]["message"])
                _save("ddb_operation_logs.json", op_logs)
                return er
            cond = {"op": op, "value": v[1], "type": v[0]}

    if limit is None:
        limit = 100
    if (not isinstance(limit, int)) or isinstance(limit, bool) or limit < 1:
        er = _err("VALIDATION_ERROR", "limit must be an integer >= 1", field="limit")
        _append_log(op_logs, table.get("account_id"), table_id, index_id, er, False, err_code="ValidationException", err_msg=er["error"]["message"])
        _save("ddb_operation_logs.json", op_logs)
        return er

    if filter is not None and not isinstance(filter, dict):
        er = _err("VALIDATION_ERROR", "filter must be an object (attribute -> exact match)", field="filter")
        _append_log(op_logs, table.get("account_id"), table_id, index_id, er, False, err_code="ValidationException", err_msg=er["error"]["message"])
        _save("ddb_operation_logs.json", op_logs)
        return er

    if scan_index_forward is None:
        scan_index_forward = True
    if not isinstance(scan_index_forward, bool):
        er = _err("VALIDATION_ERROR", "scan_index_forward must be a boolean", field="scan_index_forward")
        _append_log(op_logs, table.get("account_id"), table_id, index_id, er, False, err_code="ValidationException", err_msg=er["error"]["message"])
        _save("ddb_operation_logs.json", op_logs)
        return er

    # Key selection from base-table storage: we only have primary key columns, so index queries behave like table queries,
    # but we still enforce that the index exists & its key schema is used for conditions (types).
    def _key_field(prefix, t):
        return {"S": f"{prefix}_s", "N": f"{prefix}_n", "B": f"{prefix}_b"}[t]

    pk_field = _key_field("pk", pk_parsed[0])
    pk_val = pk_parsed[1]

    sk_field = _key_field("sk", key_range_type) if key_range_type else None

    # Gather matching ACTIVE items by partition key
    candidates = []
    for it in items:
        if not isinstance(it, dict):
            continue
        if it.get("table_id") != table_id:
            continue
        if it.get("status") != "ACTIVE":
            continue
        if it.get(pk_field) != pk_val:
            continue
        # ensure composite key isn't mismatched
        for f in ("pk_s", "pk_n", "pk_b"):
            if f != pk_field and it.get(f) is not None:
                break
        else:
            candidates.append(it)

    # Apply sort key condition (only if we have a sk schema)
    if cond and sk_field:
        def _cmp(a, b):
            return (a > b) - (a < b)
        filtered = []
        for it in candidates:
            skv = it.get(sk_field)
            if skv is None:
                continue
            op = cond["op"]
            if op == "EQ" and skv == cond["value"]:
                filtered.append(it)
            elif op == "LT" and skv < cond["value"]:
                filtered.append(it)
            elif op == "LE" and skv <= cond["value"]:
                filtered.append(it)
            elif op == "GT" and skv > cond["value"]:
                filtered.append(it)
            elif op == "GE" and skv >= cond["value"]:
                filtered.append(it)
            elif op == "BETWEEN" and skv >= cond["low"] and skv <= cond["high"]:
                filtered.append(it)
            elif op == "BEGINS_WITH":
                if isinstance(skv, str) and isinstance(cond["value"], str) and skv.startswith(cond["value"]):
                    filtered.append(it)
        candidates = filtered

    # Sorting by sort key if present
    if sk_field:
        candidates.sort(key=lambda it: it.get(sk_field))
        if not scan_index_forward:
            candidates.reverse()

    # Apply non-key exact-match filters against attributes (post key selection)
    if filter:
        out = []
        for it in candidates:
            attrs = it.get("attributes") if isinstance(it.get("attributes"), dict) else {}
            ok = True
            for k, v in filter.items():
                if attrs.get(k) != v:
                    ok = False
                    break
            if ok:
                out.append(it)
        candidates = out

    # Pagination using cursor as offset
    cur = _decode_cursor(cursor)
    start = 0
    if isinstance(cur, dict) and isinstance(cur.get("offset"), int) and cur.get("offset") >= 0:
        start = int(cur["offset"])

    page = candidates[start:start + limit]
    next_cursor = None
    if start + limit < len(candidates):
        next_cursor = _make_cursor({"offset": start + limit})

    # Throttling for PROVISIONED (each returned item costs 1 RCU; minimum 1)
    rcu_cost = float(max(1, len(page)))
    if table.get("billing_mode") == "PROVISIONED":
        rcu_limit = table.get("read_capacity_units")
        if isinstance(rcu_limit, int) and rcu_limit >= 1:
            window_start = (now_dt - datetime.timedelta(seconds=1)).isoformat() + "Z"
            recent_reads = 0.0
            for r in op_logs:
                if isinstance(r, dict) and r.get("table_id") == table_id and r.get("created_at") >= window_start:
                    recent_reads += float(r.get("consumed_read_units") or 0.0)
            if recent_reads + rcu_cost > float(rcu_limit) * 1.05:
                er = _err("RATE_LIMIT", "provisioned throughput exceeded", limit=rcu_limit)
                _append_log(op_logs, table.get("account_id"), table_id, index_id, er, False, err_code="ProvisionedThroughputExceededException", err_msg="ProvisionedThroughputExceededException: read capacity exceeded", rcu=0.0)
                _save("ddb_operation_logs.json", op_logs)
                return er

    resp = {
        "items": page,
        "count": len(page),
        "scanned_count": len(candidates),
        "has_more": next_cursor is not None,
        "next_cursor": next_cursor,
    }
    _append_log(op_logs, table.get("account_id"), table_id, index_id, resp, True, rcu=rcu_cost, wcu=0.0)
    _save("ddb_operation_logs.json", op_logs)
    return resp

def scan_table(table_id, filter=None, limit=None, cursor=None, **_extra):
