def list_tables(account_id, region=None, status=None, limit=None, cursor=None, sort_by=None, sort_order=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0556000" if __import__("os").path.isdir("./environment_mix/0556000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        import random
        return prefix + "".join(random.choice(alphabet) for _ in range(17))

    def _log(account_id_log, request_obj, response_obj, ok, err_code=None, err_msg=None, rcu=0.0, wcu=0.0, http_status=None):
        logs = _load("ddb_operation_logs.json")
        op = {
            "op_id": _new_id("ddb_op_"),
            "account_id": account_id_log if account_id_log is not None else "unknown",
            "table_id": None,
            "index_id": None,
            "tool_name": "list_tables",
            "request": request_obj,
            "response": response_obj,
            "http_status": http_status,
            "consumed_read_units": float(rcu),
            "consumed_write_units": float(wcu),
            "duration_ms": int(max(0, round((time.time() - t0) * 1000))),
            "status": "SUCCEEDED" if ok else "FAILED",
            "error_code": err_code,
            "error_message": err_msg,
            "created_at": now,
            "updated_at": now,
        }
        logs.append(op)
        _save("ddb_operation_logs.json", logs)

    req_obj = {
        "account_id": account_id,
        "region": region,
        "status": status,
        "limit": limit,
        "cursor": cursor,
        "sort_by": sort_by,
        "sort_order": sort_order,
    }

    if not isinstance(account_id, str) or not account_id.strip():
        er = _err("VALIDATION_ERROR", "account_id is required", field="account_id")
        _log("unknown", req_obj, er, False, err_code=er["error"]["code"], err_msg=er["error"]["message"], rcu=0.0)
        return er
    if region is not None and (not isinstance(region, str) or not region.strip()):
        er = _err("VALIDATION_ERROR", "region must be a non-empty string", field="region")
        _log(account_id, req_obj, er, False, err_code=er["error"]["code"], err_msg=er["error"]["message"], rcu=0.0)
        return er
    if status is not None and status not in ("CREATING", "ACTIVE", "UPDATING", "DELETING", "FAILED"):
        er = _err("VALIDATION_ERROR", "status is invalid", field="status")
        _log(account_id, req_obj, er, False, err_code=er["error"]["code"], err_msg=er["error"]["message"], rcu=0.0)
        return er
    if limit is not None:
        if not isinstance(limit, int) or isinstance(limit, bool) or limit < 1:
            er = _err("VALIDATION_ERROR", "limit must be an integer >= 1", field="limit")
            _log(account_id, req_obj, er, False, err_code=er["error"]["code"], err_msg=er["error"]["message"], rcu=0.0)
            return er
    if cursor is not None and not isinstance(cursor, str):
        er = _err("VALIDATION_ERROR", "cursor must be a string", field="cursor")
        _log(account_id, req_obj, er, False, err_code=er["error"]["code"], err_msg=er["error"]["message"], rcu=0.0)
        return er
    if sort_by is not None and sort_by not in ("created_at", "table_name", "updated_at"):
        er = _err("VALIDATION_ERROR", "sort_by is invalid", field="sort_by")
        _log(account_id, req_obj, er, False, err_code=er["error"]["code"], err_msg=er["error"]["message"], rcu=0.0)
        return er
    if sort_order is not None and sort_order not in ("asc", "desc"):
        er = _err("VALIDATION_ERROR", "sort_order is invalid", field="sort_order")
        _log(account_id, req_obj, er, False, err_code=er["error"]["code"], err_msg=er["error"]["message"], rcu=0.0)
        return er

    start_offset = 0
    if cursor is not None:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"==")
            cur = json.loads(raw.decode("utf-8"))
        except Exception:
            er = _err("VALIDATION_ERROR", "cursor is malformed", field="cursor")
            _log(account_id, req_obj, er, False, err_code=er["error"]["code"], err_msg=er["error"]["message"], rcu=0.0)
            return er
        if not isinstance(cur, dict) or cur.get("account_id") != account_id or cur.get("region") != region or cur.get("status") != status:
            er = _err("VALIDATION_ERROR", "cursor does not match request", field="cursor")
            _log(account_id, req_obj, er, False, err_code=er["error"]["code"], err_msg=er["error"]["message"], rcu=0.0)
            return er
        if not isinstance(cur.get("offset"), int) or cur.get("offset") < 0:
            er = _err("VALIDATION_ERROR", "cursor offset is invalid", field="cursor")
            _log(account_id, req_obj, er, False, err_code=er["error"]["code"], err_msg=er["error"]["message"], rcu=0.0)
            return er
        start_offset = cur["offset"]

    tables = _load("ddb_tables.json")
    rows = [t for t in tables if t.get("account_id") == account_id]

    if region is not None:
        rows = [t for t in rows if t.get("region") == region]
    if status is not None:
        rows = [t for t in rows if t.get("status") == status]
    else:
        # Exclude DELETING unless explicitly requested (no internal-caller flag in tool)
        rows = [t for t in rows if t.get("status") != "DELETING"]

    sb = sort_by or "created_at"
    so = sort_order or "asc"

    def _dt(s):
        try:
            if isinstance(s, str) and s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return datetime.datetime.min

    if sb in ("created_at", "updated_at"):
        rows.sort(key=lambda x: _dt(x.get(sb)))
    else:
        rows.sort(key=lambda x: (x.get("table_name") or "").lower())
    if so == "desc":
        rows.reverse()

    total = len(rows)
    limit_eff = 100 if limit is None else limit
    page = rows[start_offset:start_offset + limit_eff]

    # Summary shape
    summaries = []
    for t in page:
        summaries.append({
            "table_id": t.get("table_id"),
            "table_name": t.get("table_name"),
            "region": t.get("region"),
            "status": t.get("status"),
            "billing_mode": t.get("billing_mode"),
            "created_at": t.get("created_at"),
            "updated_at": t.get("updated_at"),
        })

    next_cursor = None
    if start_offset + limit_eff < total:
        cur_obj = {"account_id": account_id, "region": region, "status": status, "offset": start_offset + limit_eff}
        enc = base64.urlsafe_b64encode(json.dumps(cur_obj, separators=(",", ":")).encode("utf-8")).decode("utf-8").rstrip("=")
        next_cursor = enc

    consumed_rcu = 0.5 + 0.1 * len(summaries)
    resp = {
        "tables": summaries,
        "count": len(summaries),
        "total": total,
        "has_more": next_cursor is not None,
        "next_cursor": next_cursor,
    }
    _log(account_id, req_obj, resp, True, rcu=consumed_rcu, wcu=0.0)
    return resp
